insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AGR-201', 'The Founder Knows the Crop but Not the Selling', 'Founder Psychology', 'internal', 'The founder understands farming or the technology deeply, but the part the business now needs — selling, pricing, collecting money — is the part they have never done. The gap is filled by working harder at what they already know.', 5, 9, '["Strong on farming or tech, weak on selling", "Avoids pricing and collection conversations", "Spends time on the part they enjoy", "No plan to learn the missing skill"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["agritech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-201-1', (select problem_id from problems where problem_code = 'AGR-201'), 'Comfort in the Known Skill', 'Psychological', 'The founder returns to the work they are already good at because it feels productive, while the skill the business actually needs goes unlearned.', 0.73, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-201-2', (select problem_id from problems where problem_code = 'AGR-201'), 'Selling Never Learned', 'Knowledge', 'Nobody taught the founder how to sell or how to ask for payment, and they have not sought it out, so the business grows only as far as word of mouth carries it.', 0.70, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-201-3', (select problem_id from problems where problem_code = 'AGR-201'), 'Gap Not Named', 'Behavioural', 'The founder has not written down what they are weak at, so it is never addressed deliberately.', 0.66, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-201-1', (select problem_id from problems where problem_code = 'AGR-201'), '["RC-AGR-201-1", "RC-AGR-201-2", "RC-AGR-201-3"]'::jsonb, 'Founder Leverage', 'Agriculture & AgriTech — Founder Skill Fit', '[]'::jsonb, '["Write down the two things this business needs that you have never done.", "Pick one and find a person who does it well to sit with for two hours.", "Do that one thing yourself ten times before you hand it to anyone."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["Name the gap before trying to close it.", "You cannot delegate a skill you have never practised."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-201-2', (select problem_id from problems where problem_code = 'AGR-201'), '["RC-AGR-201-1", "RC-AGR-201-2", "RC-AGR-201-3"]'::jsonb, 'Founder Leverage', 'Agriculture & AgriTech — Founder Skill Fit', '[]'::jsonb, '["List where your last month of hours went, then mark which hours only you could do.", "Move four hours a week from what you enjoy to what the business needs.", "Check after a month whether the number moved."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["Growth usually needs the skill the founder likes least."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into questions (question_code, category, question_text, problem_id, root_cause_id, question_type, difficulty_level, priority, is_distress_tagged, red_flag_pattern, green_flag_pattern, primary_stage_group, industry_relevance) values ('S0-AGR-201-1', 'Founder Psychology', 'What part of running this business have you never done before?', (select problem_id from problems where problem_code = 'AGR-201'), (select root_cause_id from root_causes where root_cause_code = 'RC-AGR-201-1'), 'open_text', 2, 'CORE', false, 'Cannot name anything, or says nothing is missing', 'Names something specific and is honest about it', 'Stage 0', '["agritech"]'::jsonb) on conflict (question_code) do nothing;
