insert into questions (question_code, category, question_text, problem_id, root_cause_id, question_type, difficulty_level, priority, is_distress_tagged, red_flag_pattern, green_flag_pattern, primary_stage_group, industry_relevance) values ('S0-AGR-201-2', 'Founder Psychology', 'Which do you find easier — growing the produce or selling it? Why?', (select problem_id from problems where problem_code = 'AGR-201'), (select root_cause_id from root_causes where root_cause_code = 'RC-AGR-201-1'), 'open_text', 2, 'CORE', false, 'Avoids the selling side and has no plan for it', 'Knows which is harder for them and is working on it', 'Stage 0', '["agritech"]'::jsonb) on conflict (question_code) do nothing;
