insert into questions (question_code, category, question_text, problem_id, root_cause_id, question_type, difficulty_level, priority, is_distress_tagged, red_flag_pattern, green_flag_pattern, primary_stage_group, industry_relevance) values ('S10-AGR-201-2', 'Founder Psychology', 'Who teaches you the parts of this business you do not know?', (select problem_id from problems where problem_code = 'AGR-201'), (select root_cause_id from root_causes where root_cause_code = 'RC-AGR-201-3'), 'open_text', 2, 'CORE', false, 'Nobody', 'Names a mentor, peer or advisor they actually use', 'Stage 1→10+', '["agritech"]'::jsonb) on conflict (question_code) do nothing;
