insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AGR-202', 'All the Founder''s Hours Go to the Field', 'Founder Psychology', 'internal', 'The founder spends the day with farmers, in the field or at the mandi, and the work of running the business happens late at night or not at all. Field work always feels more urgent, so it always wins.', 5, 9, '["Whole day spent in the field", "Business work done late or skipped", "No time set aside for planning", "Cannot remember the last full day off"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["agritech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-202-1', (select problem_id from problems where problem_code = 'AGR-202'), 'Field Work Always Feels Urgent', 'Behavioural', 'Something in the field always needs attention today, so the work that pays off next month never gets a turn.', 0.74, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-202-2', (select problem_id from problems where problem_code = 'AGR-202'), 'No Time Protected for the Business', 'Operational', 'No hours are reserved for planning, pricing or numbers, so those happen only when everything else is done, which is never.', 0.71, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-202-3', (select problem_id from problems where problem_code = 'AGR-202'), 'Being Busy Read as Progress', 'Psychological', 'A full day in the field feels like a productive day, which hides the fact that the business itself is not moving.', 0.66, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-202-1', (select problem_id from problems where problem_code = 'AGR-202'), '["RC-AGR-202-1", "RC-AGR-202-2", "RC-AGR-202-3"]'::jsonb, 'Founder Leverage', 'Agriculture & AgriTech — Founder Time Use', '[]'::jsonb, '["Block half a day each week for business work and do not move it.", "Write down what you will use that time for before the week starts.", "After a month, check what that half-day produced."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["A day full of urgent work can still be a day the business did not move.", "Protect the time first; the work will fill it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-202-2', (select problem_id from problems where problem_code = 'AGR-202'), '["RC-AGR-202-1", "RC-AGR-202-2", "RC-AGR-202-3"]'::jsonb, 'Founder Leverage', 'Agriculture & AgriTech — Founder Time Use', '[]'::jsonb, '["Write what you did every hour for one week.", "Mark the hours only you could have done.", "Give away one task from the unmarked list."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["You cannot fix how you spend time until you can see it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
