insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AGR-203', 'Farmers Trust the Founder, Not the Company', 'Founder Psychology', 'internal', 'Farmers deal with the business because they trust the founder personally. Nobody else can hold those relationships, so the founder cannot be absent and the business cannot grow past their own contact list.', 5, 9, '["Farmers ask for the founder by name", "Nobody else can hold the relationship", "Founder present at every collection or payment", "Growth limited by the founder''s contacts"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["agritech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-203-1', (select problem_id from problems where problem_code = 'AGR-203'), 'Trust Built Person to Person Only', 'Behavioural', 'Every relationship was built by the founder directly and never transferred, so the trust belongs to a person rather than to the company.', 0.75, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-203-2', (select problem_id from problems where problem_code = 'AGR-203'), 'No Second Face for the Business', 'Operational', 'No field officer or partner has been introduced as someone farmers can also rely on, so there is no alternative when the founder is away.', 0.71, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-203-3', (select problem_id from problems where problem_code = 'AGR-203'), 'Presence Mistaken for Service', 'Psychological', 'The founder believes turning up personally is the service, so reducing it feels like reducing quality.', 0.67, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-203-1', (select problem_id from problems where problem_code = 'AGR-203'), '["RC-AGR-203-1", "RC-AGR-203-2", "RC-AGR-203-3"]'::jsonb, 'Founder Leverage', 'Agriculture & AgriTech — Founder Dependency', '[]'::jsonb, '["Pick ten farmers and take a team member with you for the next three visits.", "Let that person handle the fourth visit alone and ask the farmer how it went.", "Repeat until the farmer calls them first."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["Trust transfers by showing up together, not by announcing a change.", "The test is who the farmer calls, not who you told them to call."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-203-2', (select problem_id from problems where problem_code = 'AGR-203'), '["RC-AGR-203-1", "RC-AGR-203-2", "RC-AGR-203-3"]'::jsonb, 'Founder Leverage', 'Agriculture & AgriTech — Founder Dependency', '[]'::jsonb, '["Write down what you say and promise on a farmer visit.", "Give that to the person taking over so the promises stay the same.", "Check three farmers a month to see the promises are being kept."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["If your promises are not written, only you can keep them."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
