insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AGR-204', 'Nobody Is Sure Who Does What in the Field', 'Team & Leadership', 'internal', 'Field staff take on whatever comes up, so tasks are covered by whoever is nearest rather than by whoever owns them. Things get missed and nobody can be asked why, because nobody was responsible.', 5, 9, '["Field staff do whatever comes up", "Tasks missed with no one accountable", "No written duties", "Same work done twice by different people"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["agritech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-204-1', (select problem_id from problems where problem_code = 'AGR-204'), 'Duties Never Written Down', 'Operational', 'No one has written what each field person is responsible for, so ownership is decided fresh every day.', 0.74, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-204-2', (select problem_id from problems where problem_code = 'AGR-204'), 'Everyone Covers Everything', 'Behavioural', 'Staff are praised for pitching in anywhere, which sounds good but means nothing has a real owner.', 0.70, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-204-3', (select problem_id from problems where problem_code = 'AGR-204'), 'No Check That Work Happened', 'Operational', 'There is no simple check that each duty was done, so gaps show up only when a farmer complains.', 0.67, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-204-1', (select problem_id from problems where problem_code = 'AGR-204'), '["RC-AGR-204-1", "RC-AGR-204-2", "RC-AGR-204-3"]'::jsonb, 'Team Effectiveness', 'Agriculture & AgriTech — Role Clarity', '[]'::jsonb, '["Write one line per person: the three things they are responsible for.", "Read it out to the team and fix the arguments it causes.", "Put it where they can see it."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["Two people covering everything means nobody covers anything.", "The arguments the list causes are the point of writing it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-204-2', (select problem_id from problems where problem_code = 'AGR-204'), '["RC-AGR-204-1", "RC-AGR-204-2", "RC-AGR-204-3"]'::jsonb, 'Team Effectiveness', 'Agriculture & AgriTech — Role Clarity', '[]'::jsonb, '["Make a simple daily check of the three duties that matter most.", "Ask the owner, not the group, when something is missed.", "Review the misses once a week."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["Ask a person, not a room."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
