insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AGR-205', 'Only the Founder Can Agree a Price', 'Team & Leadership', 'internal', 'Every procurement price, rate change and payment exception waits for the founder. Field staff cannot close anything on the spot, so deals are lost to whoever can answer faster.', 5, 9, '["Every price waits for the founder", "Field staff cannot agree anything", "Deals lost to slower response", "No limits anyone can work within"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["agritech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-205-1', (select problem_id from problems where problem_code = 'AGR-205'), 'No Limits Given to Anyone', 'Operational', 'Nobody has been told the range they can agree within, so every decision has to come back to the founder.', 0.75, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
