insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AGR-206', 'Field Staff Are Hired Because They Were Available', 'Team & Leadership', 'internal', 'People are taken on when the work piles up, from whoever is around, with no idea of the role or how they will be judged. Some work out and some do not, and nobody can say why.', 5, 9, '["Hired when work piles up", "No role described before hiring", "No way to judge if they are doing well", "High turnover with no reason known"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["agritech"]'::jsonb) on conflict (problem_code) do nothing;
