insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AGR-207', 'This Season''s Work Has Nothing to Do With the Plan for the Business', 'Strategy & Planning', 'internal', 'The business runs season to season, reacting to crop, weather and price. Where it is meant to be in three years is a separate conversation that never touches what gets done this month.', 5, 9, '["Runs season to season", "Three-year picture unconnected to this month", "No written plan the team has seen", "Cannot say what this season is building toward"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["agritech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-207-1', (select problem_id from problems where problem_code = 'AGR-207'), 'No Written Plan to Work From', 'Strategic', 'The direction lives in the founder''s head, so nothing this season can be checked against it.', 0.75, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-207-2', (select problem_id from problems where problem_code = 'AGR-207'), 'Season Pressure Overrides Direction', 'Behavioural', 'Each season''s urgency decides the work, so the longer plan never gets a share of the effort.', 0.71, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-207-3', (select problem_id from problems where problem_code = 'AGR-207'), 'No Marker of Progress', 'Knowledge', 'There is no measure that says whether this season moved the business forward, only whether it was survived.', 0.67, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-207-1', (select problem_id from problems where problem_code = 'AGR-207'), '["RC-AGR-207-1", "RC-AGR-207-2", "RC-AGR-207-3"]'::jsonb, 'Strategic Focus', 'Agriculture & AgriTech — Plan and Vision', '[]'::jsonb, '["Write in five lines where you want this business to be in three years.", "Name the one thing this season must achieve to move toward it.", "Tell your team both, and check at season end."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["A plan nobody has read cannot guide anything.", "One goal per season beats five."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-207-2', (select problem_id from problems where problem_code = 'AGR-207'), '["RC-AGR-207-1", "RC-AGR-207-2", "RC-AGR-207-3"]'::jsonb, 'Strategic Focus', 'Agriculture & AgriTech — Plan and Vision', '[]'::jsonb, '["Pick one number that tells you the business is moving, not just busy.", "Write down where it is now.", "Check it at the end of every season."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["Surviving a season and progressing are not the same thing."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
