insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AGR-208', 'Chasing Every Crop and Every District at Once', 'Strategy & Planning', 'internal', 'New crops, new districts and new buyer types are added whenever an opportunity appears, so the team is spread thin and nothing gets strong enough to be reliable.', 5, 9, '["Many crops and districts at once", "Team spread thin", "Nothing done well enough to repeat", "Cannot name what has been turned down"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["agritech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-208-1', (select problem_id from problems where problem_code = 'AGR-208'), 'Nothing Ever Refused', 'Strategic', 'Every opportunity is taken because refusing feels like losing, so effort is never concentrated anywhere.', 0.75, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-208-2', (select problem_id from problems where problem_code = 'AGR-208'), 'No Rule for Saying No', 'Operational', 'There is no test an opportunity has to pass, so each one is judged on its own and each one sounds good.', 0.71, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-208-3', (select problem_id from problems where problem_code = 'AGR-208'), 'Fear of Missing Out', 'Psychological', 'The founder worries a passed-up crop or district was the one that would have worked, so nothing is passed up.', 0.67, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AGR-208-1', (select problem_id from problems where problem_code = 'AGR-208'), '["RC-AGR-208-1", "RC-AGR-208-2", "RC-AGR-208-3"]'::jsonb, 'Strategic Focus', 'Agriculture & AgriTech — Prioritisation', '[]'::jsonb, '["List everything you are currently doing: crops, districts, buyer types.", "Pick the two you will be strongest in this year and say so out loud.", "Write what you are therefore not doing."]'::jsonb, '[3, 4, 5]'::jsonb, '["agritech"]'::jsonb, '["Focus is a list of what you refused.", "Two things done well beat six done partly."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
