insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AGR-209', 'Farmer and Crop Records Live in the Founder''s Memory and a Notebook', 'Strategy & Planning', 'internal', 'Which farmer grows what, what they were paid last time, what went wrong with a batch — all of it is remembered or scribbled somewhere personal. When the season turns or a person leaves, it is gone.', 5, 9, '["Farmer details in a personal notebook", "Past prices remembered, not recorded", "Batch problems not written down", "Same mistakes repeat each season"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["agritech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-209-1', (select problem_id from problems where problem_code = 'AGR-209'), 'Records Kept Personally', 'Operational', 'Farmer and crop details sit in the founder''s notebook or phone rather than anywhere the business can use.', 0.75, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-209-2', (select problem_id from problems where problem_code = 'AGR-209'), 'Problems Not Written After They Happen', 'Behavioural', 'A bad batch or a failed payment is dealt with and moved on from, with nothing recorded, so the same thing happens again.', 0.71, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AGR-209-3', (select problem_id from problems where problem_code = 'AGR-209'), 'Nothing to Hand Over', 'Knowledge', 'Because nothing is written, a new person starts with no history and has to learn it by making the same errors.', 0.68, 'internal', 'Stage 0→1', '["agritech"]'::jsonb) on conflict (root_cause_code) do nothing;
