insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AUT-201', 'A Good Mechanic Running a Business They Were Never Taught', 'Founder Psychology', 'internal', 'The founder knows vehicles better than anyone on the floor, but pricing a job, chasing payment and reading the month''s numbers are things nobody taught them. So they stay on the tools where they are strong.', 5, 9, '["Strong technically, weak commercially", "Avoids pricing and collections", "Still on the tools daily", "Cannot read the month''s numbers"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["automotive"]'::jsonb) on conflict (problem_code) do nothing;
