insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AUT-203', 'Customers Only Trust the Founder''s Diagnosis', 'Founder Psychology', 'internal', 'Customers want the founder to look at the vehicle themselves. Other staff can do the work but not the diagnosis or the conversation, so the founder is the bottleneck on every job that comes in.', 5, 9, '["Customers insist on the founder looking", "Staff can repair but not diagnose", "Founder handles every customer conversation", "Jobs wait for the founder to be free"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["automotive"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AUT-203-1', (select problem_id from problems where problem_code = 'AUT-203'), 'Diagnosis Never Taught', 'Knowledge', 'The founder has never sat with a staff member and taught them how they work out a fault, so nobody else can.', 0.75, 'internal', 'Stage 0→1', '["automotive"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AUT-203-2', (select problem_id from problems where problem_code = 'AUT-203'), 'Customer Expectation Never Reset', 'Behavioural', 'Customers were always dealt with by the founder, so they have learned to expect it and nobody has changed that.', 0.71, 'internal', 'Stage 0→1', '["automotive"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AUT-203-3', (select problem_id from problems where problem_code = 'AUT-203'), 'Trust Tied to the Founder''s Eye', 'Psychological', 'The founder believes only they can spot the real fault, so they never test whether a trained person can.', 0.67, 'internal', 'Stage 0→1', '["automotive"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AUT-203-1', (select problem_id from problems where problem_code = 'AUT-203'), '["RC-AUT-203-1", "RC-AUT-203-2", "RC-AUT-203-3"]'::jsonb, 'Founder Leverage', 'Automotive & Mobility — Founder Dependency', '[]'::jsonb, '["Take one staff member with you on every diagnosis for two weeks.", "Have them do the next one while you watch and say nothing.", "Let them explain it to the customer."]'::jsonb, '[3, 4, 5]'::jsonb, '["automotive"]'::jsonb, '["Teach the thinking, not just the repair.", "The test is whether the customer accepts their explanation."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-AUT-203-2', (select problem_id from problems where problem_code = 'AUT-203'), '["RC-AUT-203-1", "RC-AUT-203-2", "RC-AUT-203-3"]'::jsonb, 'Founder Leverage', 'Automotive & Mobility — Founder Dependency', '[]'::jsonb, '["Write the ten faults you see most and how you check each one.", "Put it where the team can read it.", "Ask a staff member to work a job from it."]'::jsonb, '[3, 4, 5]'::jsonb, '["automotive"]'::jsonb, '["Written checks turn your judgement into something teachable."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
