insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AUT-204-1', (select problem_id from problems where problem_code = 'AUT-204'), 'Duties Not Written', 'Operational', 'Nobody wrote who owns the customer, the parts and the final check, so each is done by whoever thinks of it.', 0.74, 'internal', 'Stage 0→1', '["automotive"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AUT-204-2', (select problem_id from problems where problem_code = 'AUT-204'), 'Handover Between Roles Undefined', 'Operational', 'The point where a job passes from advisor to mechanic and back is not defined, so things are dropped there.', 0.70, 'internal', 'Stage 0→1', '["automotive"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AUT-204-3', (select problem_id from problems where problem_code = 'AUT-204'), 'No Final Check Owner', 'Behavioural', 'Nobody is responsible for looking at a finished job before the customer does.', 0.68, 'internal', 'Stage 0→1', '["automotive"]'::jsonb) on conflict (root_cause_code) do nothing;
