insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AUT-205-3', (select problem_id from problems where problem_code = 'AUT-205'), 'Cost of a Goodwill Job Unknown', 'Knowledge', 'Because nobody knows what a goodwill repair costs the business, no sensible limit can be set.', 0.67, 'internal', 'Stage 0→1', '["automotive"]'::jsonb) on conflict (root_cause_code) do nothing;
