insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('AUT-209', 'Job History and Known Fixes Are Not Written Down', 'Strategy & Planning', 'internal', 'What was done to a vehicle last time, which fault keeps coming back, what the trick is on a particular model — it is all in people''s heads. When a mechanic leaves, it leaves with them.', 5, 9, '["No job history per vehicle", "Known fixes not written", "Same faults re-diagnosed from scratch", "Knowledge leaves with the mechanic"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["automotive"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AUT-209-1', (select problem_id from problems where problem_code = 'AUT-209'), 'No Job Record Kept', 'Operational', 'Work done on a vehicle is not recorded against it, so the next visit starts with no history.', 0.75, 'internal', 'Stage 0→1', '["automotive"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AUT-209-2', (select problem_id from problems where problem_code = 'AUT-209'), 'Fixes Never Written Up', 'Knowledge', 'The tricks the team has learned on particular models are never written down, so each person re-learns them.', 0.71, 'internal', 'Stage 0→1', '["automotive"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-AUT-209-3', (select problem_id from problems where problem_code = 'AUT-209'), 'Nothing to Hand Over', 'Behavioural', 'When someone leaves, no record exists of what they knew, so it is simply lost.', 0.68, 'internal', 'Stage 0→1', '["automotive"]'::jsonb) on conflict (root_cause_code) do nothing;
