insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('BFS-201', 'Strong on the Product, New to Being Regulated', 'Founder Psychology', 'internal', 'The founder can build or sell the product, but licensing, compliance and what a regulator expects are things they are learning as they go. The risk is carried without being understood.', 5, 9, '["Learning compliance while operating", "No one on the team has done it before", "Rules understood roughly, not precisely", "Hopes nothing is checked yet"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["fintech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-201-1', (select problem_id from problems where problem_code = 'BFS-201'), 'Compliance Learned on the Job', 'Knowledge', 'Nobody on the team has been through a regulated business before, so the rules are interpreted rather than known.', 0.75, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
