insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-201-3', (select problem_id from problems where problem_code = 'BFS-201'), 'No Advisor Engaged', 'Behavioural', 'No lawyer or compliance person has been brought in, because it feels early and expensive.', 0.68, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-BFS-201-1', (select problem_id from problems where problem_code = 'BFS-201'), '["RC-BFS-201-1", "RC-BFS-201-2", "RC-BFS-201-3"]'::jsonb, 'Founder Leverage', 'BFSI / FinTech — Founder Skill Fit', '[]'::jsonb, '["Write down every rule you think applies to you, and mark which you are sure about.", "Take the unsure list to someone who has done this before.", "Fix the two that would stop the business if you got them wrong."]'::jsonb, '[3, 4, 5]'::jsonb, '["fintech"]'::jsonb, '["Write what you are unsure about — that list is the real risk.", "One conversation with someone experienced beats a month of reading."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
