insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('BFS-202', 'Firefighting Customer Issues Instead of Building the Business', 'Founder Psychology', 'internal', 'Failed transactions, angry customers and reconciliation problems fill the founder''s day. The work that would reduce those problems never gets time, so the firefighting continues.', 5, 9, '["Day spent on failed transactions and complaints", "No time to fix root causes", "Reconciliation done late at night", "Same problems every week"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["fintech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-202-1', (select problem_id from problems where problem_code = 'BFS-202'), 'Symptoms Handled, Causes Left', 'Behavioural', 'Each issue is resolved for the customer and the underlying cause is never worked on, so the same issues return.', 0.74, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-202-2', (select problem_id from problems where problem_code = 'BFS-202'), 'No Time Set Aside to Fix Causes', 'Operational', 'No hours are reserved for fixing the reason problems happen, so only the problems themselves get attention.', 0.71, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-202-3', (select problem_id from problems where problem_code = 'BFS-202'), 'Responsiveness Feels Like the Job', 'Psychological', 'Answering every customer personally feels like good service and hides that the service keeps failing.', 0.67, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
