insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('BFS-203', 'Every Partner and Bank Relationship Sits With the Founder', 'Founder Psychology', 'internal', 'Banks, payment partners and large customers all deal with the founder directly. Nobody else has met them, so the business cannot operate or negotiate without the founder in the room.', 5, 9, '["Founder is the only contact for partners", "Nobody else has met the bank", "Negotiations wait for the founder", "Partner knowledge unwritten"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["fintech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-203-1', (select problem_id from problems where problem_code = 'BFS-203'), 'Single Point of Contact by Default', 'Operational', 'Every partner relationship started with the founder and was never widened, so there is no second contact anywhere.', 0.75, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-203-2', (select problem_id from problems where problem_code = 'BFS-203'), 'Partner Terms Not Written Down', 'Knowledge', 'What was agreed, and why, lives in the founder''s memory and emails rather than in a record the team can use.', 0.71, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-203-3', (select problem_id from problems where problem_code = 'BFS-203'), 'Relationships Held Closely', 'Psychological', 'The founder believes partners will only take them seriously, so the relationships are guarded rather than shared.', 0.67, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-BFS-203-1', (select problem_id from problems where problem_code = 'BFS-203'), '["RC-BFS-203-1", "RC-BFS-203-2", "RC-BFS-203-3"]'::jsonb, 'Founder Leverage', 'BFSI / FinTech — Founder Dependency', '[]'::jsonb, '["Take one team member to the next three partner meetings.", "Write down what is agreed with each partner and where it is recorded.", "Let that person run the fourth meeting."]'::jsonb, '[3, 4, 5]'::jsonb, '["fintech"]'::jsonb, '["A partner with one contact is a risk to both sides.", "Write the terms so someone else can hold the relationship."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
