insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('BFS-204', 'Nobody Owns Whether the Numbers Balance', 'Team & Leadership', 'internal', 'Reconciliation, dispute handling and customer refunds are done by whoever notices. When money does not match, there is no one person whose job it was to catch it.', 5, 9, '["Reconciliation done by whoever notices", "No owner for disputes", "Refunds handled inconsistently", "Money mismatches found late"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["fintech"]'::jsonb) on conflict (problem_code) do nothing;
