insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-204-3', (select problem_id from problems where problem_code = 'BFS-204'), 'Found Late, Not Prevented', 'Behavioural', 'Mismatches are discovered days later during a bigger check, by which time the cause is hard to trace.', 0.68, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
