insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('BFS-206', 'Hired for Speed, Not for the Care This Business Needs', 'Team & Leadership', 'internal', 'People are hired quickly when volume grows, without checking whether they are careful with money and rules. In a regulated business, one careless hire is a different kind of risk.', 5, 9, '["Hired fast under volume pressure", "Care and accuracy not tested", "No background or reference checks", "Errors traced to specific hires"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["fintech"]'::jsonb) on conflict (problem_code) do nothing;
