insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-206-2', (select problem_id from problems where problem_code = 'BFS-206'), 'Role Not Described', 'Operational', 'The need is volume, not a role, so nothing is written to measure the person against.', 0.70, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
