insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('BFS-209', 'Why Decisions Were Made Is Not Written Anywhere', 'Strategy & Planning', 'internal', 'Why a rule was interpreted a certain way, why a partner term was accepted, what a past incident taught — none of it is recorded. In a regulated business, being unable to explain a past decision is its own problem.', 5, 9, '["Decision reasoning not recorded", "Past incidents not written up", "Rule interpretations held in memory", "Cannot explain why something was done"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["fintech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-209-1', (select problem_id from problems where problem_code = 'BFS-209'), 'No Decision Record', 'Operational', 'Decisions are made in conversation and never written with their reasoning, so they cannot be explained or revisited later.', 0.76, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-209-2', (select problem_id from problems where problem_code = 'BFS-209'), 'Incidents Closed Without a Write-Up', 'Behavioural', 'An incident is fixed for the customer and never written up, so nothing is learned and nothing can be shown.', 0.72, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BFS-209-3', (select problem_id from problems where problem_code = 'BFS-209'), 'Knowledge Leaves With People', 'Knowledge', 'Interpretations and history sit with individuals, so each departure costs the business its memory.', 0.68, 'internal', 'Stage 0→1', '["fintech"]'::jsonb) on conflict (root_cause_code) do nothing;
