insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('BPC-202', 'Every Hour Is on the Chair, So the Salon Never Gets Run', 'Founder Psychology', 'internal', 'The owner''s own appointments are the biggest source of takings, so there are no hours left to run the salon. Stepping off the chair feels like losing money.', 5, 9, '["Owner''s chair hours are the main income", "No hours for running the salon", "Admin done after closing", "No full day off in memory"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["beauty_personal_care"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BPC-202-1', (select problem_id from problems where problem_code = 'BPC-202'), 'Owner Hours Counted as Income', 'Operational', 'Because the owner''s chair time is the biggest earner, time spent managing feels like lost money and never gets booked.', 0.75, 'internal', 'Stage 0→1', '["beauty_personal_care"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BPC-202-2', (select problem_id from problems where problem_code = 'BPC-202'), 'Nothing Protected in the Diary', 'Behavioural', 'No hours are blocked out, so clients fill every slot and the business work goes to the end of the day.', 0.71, 'internal', 'Stage 0→1', '["beauty_personal_care"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BPC-202-3', (select problem_id from problems where problem_code = 'BPC-202'), 'A Full Diary Feels Like Success', 'Psychological', 'A fully booked day feels like a good day, which hides that the salon itself is not improving.', 0.67, 'internal', 'Stage 0→1', '["beauty_personal_care"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-BPC-202-1', (select problem_id from problems where problem_code = 'BPC-202'), '["RC-BPC-202-1", "RC-BPC-202-2", "RC-BPC-202-3"]'::jsonb, 'Founder Leverage', 'Beauty & Personal Care — Founder Time Use', '[]'::jsonb, '["Block two half-days a week out of the diary and do not give them away.", "Decide what they are for before the week starts.", "Check at month end what the salon earned in hours you were not on the chair."]'::jsonb, '[3, 4, 5]'::jsonb, '["beauty_personal_care"]'::jsonb, '["Block the time first; clients will fill whatever is left open.", "Measure what the salon earns without you, not just what you earn."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-BPC-202-2', (select problem_id from problems where problem_code = 'BPC-202'), '["RC-BPC-202-1", "RC-BPC-202-2", "RC-BPC-202-3"]'::jsonb, 'Founder Leverage', 'Beauty & Personal Care — Founder Time Use', '[]'::jsonb, '["Write what you did hour by hour for a week.", "Mark the hours only you could do.", "Give one task away."]'::jsonb, '[3, 4, 5]'::jsonb, '["beauty_personal_care"]'::jsonb, '["You cannot fix your time until you can see it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
