insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('BPC-203', 'Regular Clients Will Only See the Owner', 'Founder Psychology', 'internal', 'Clients book the owner by name and refuse other stylists. The salon''s income depends on one person''s hands, and handing a client over risks losing them.', 5, 9, '["Clients book the owner by name", "Refuse other stylists", "Handing over risks losing the client", "No second stylist trained to the standard"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["beauty_personal_care"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BPC-203-1', (select problem_id from problems where problem_code = 'BPC-203'), 'Loyalty Attached to a Person', 'Behavioural', 'Clients were won by the owner personally and never introduced to anyone else, so the loyalty is to a person, not the salon.', 0.75, 'internal', 'Stage 0→1', '["beauty_personal_care"]'::jsonb) on conflict (root_cause_code) do nothing;
