insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-BPC-203-3', (select problem_id from problems where problem_code = 'BPC-203'), 'Handover Never Attempted', 'Psychological', 'The owner fears losing the client more than being the bottleneck, so it is never tried.', 0.67, 'internal', 'Stage 0→1', '["beauty_personal_care"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-BPC-203-1', (select problem_id from problems where problem_code = 'BPC-203'), '["RC-BPC-203-1", "RC-BPC-203-2", "RC-BPC-203-3"]'::jsonb, 'Founder Leverage', 'Beauty & Personal Care — Founder Dependency', '[]'::jsonb, '["Pick five regulars and do the next three visits together with a second stylist.", "Let that stylist do the fourth alone while you are in the salon.", "Ask the client afterwards how it went."]'::jsonb, '[3, 4, 5]'::jsonb, '["beauty_personal_care"]'::jsonb, '["Hand over by working together, not by announcing it.", "The test is whether the client rebooks with them."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
