insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PRP-201', 'Knows How to Build, Not How to Fund and Sell', 'Founder Psychology', 'internal', 'The founder can run a site and manage contractors, but raising money, pricing a project and selling units are skills nobody taught them. Those decisions get made on instinct.', 5, 9, '["Strong on site, weak on funding and sales", "Project pricing done on instinct", "Avoids buyer and investor conversations", "Cannot say if a project actually made money"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["proptech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-201-1', (select problem_id from problems where problem_code = 'PRP-201'), 'Site Is the Comfort Zone', 'Psychological', 'The founder is confident on site, so that is where the day goes while funding and sales are left to instinct.', 0.74, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-201-2', (select problem_id from problems where problem_code = 'PRP-201'), 'Funding and Sales Never Learned', 'Knowledge', 'Nobody taught the founder how to structure funding or price a project, and they have not sought it out.', 0.71, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-201-3', (select problem_id from problems where problem_code = 'PRP-201'), 'Project Outcome Never Checked', 'Behavioural', 'Projects are finished and moved on from without working out what each actually earned.', 0.68, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PRP-201-1', (select problem_id from problems where problem_code = 'PRP-201'), '["RC-PRP-201-1", "RC-PRP-201-2", "RC-PRP-201-3"]'::jsonb, 'Founder Leverage', 'Construction & Real Estate / PropTech — Founder Skill Fit', '[]'::jsonb, '["Work out what your last completed project actually made, after everything.", "Write the two skills this business needs that you have never done.", "Take the bigger one to someone who has done it."]'::jsonb, '[3, 4, 5]'::jsonb, '["proptech"]'::jsonb, '["Finishing a project and making money on it are different things.", "Start with the last project''s real number."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-PRP-201-2', (select problem_id from problems where problem_code = 'PRP-201'), '["RC-PRP-201-1", "RC-PRP-201-2", "RC-PRP-201-3"]'::jsonb, 'Founder Leverage', 'Construction & Real Estate / PropTech — Founder Skill Fit', '[]'::jsonb, '["Write where your hours went last month.", "Mark the hours only you could do.", "Hand one site task to a trusted person this month."]'::jsonb, '[3, 4, 5]'::jsonb, '["proptech"]'::jsonb, '["Site work is the easiest place to avoid the business."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
