insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-202-3', (select problem_id from problems where problem_code = 'PRP-202'), 'Presence Read as Control', 'Psychological', 'Being on site feels like the only way to keep quality, so the founder never tests whether it is.', 0.67, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
