insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PRP-203', 'Contractors and Buyers Only Deal With the Founder', 'Founder Psychology', 'internal', 'Contractors take instructions only from the founder, and buyers want to hear it from them. Nothing moves when the founder is not reachable, and there is no second person anyone trusts.', 5, 9, '["Contractors take instruction only from the founder", "Buyers insist on the founder", "Work stops when the founder is unreachable", "No second point of contact"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["proptech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-203-1', (select problem_id from problems where problem_code = 'PRP-203'), 'Authority Never Shared', 'Operational', 'No one else was given authority with contractors, so instructions from anyone else are ignored.', 0.75, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-203-2', (select problem_id from problems where problem_code = 'PRP-203'), 'Buyer Trust Built Personally', 'Behavioural', 'Buyers were always handled by the founder and never introduced to anyone else.', 0.71, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-203-3', (select problem_id from problems where problem_code = 'PRP-203'), 'Nothing Written for Others to Use', 'Knowledge', 'What was agreed with each contractor and buyer lives in the founder''s memory, so nobody else could step in.', 0.68, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
