insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PRP-204', 'Nobody Owns Whether the Site Is Actually on Schedule', 'Team & Leadership', 'internal', 'Material ordering, contractor coordination and checking progress are done by whoever is available. When the project slips, there is no one whose job it was to see it coming.', 5, 9, '["Ordering and coordination done by whoever is free", "No owner for the schedule", "Slippage found late", "No written duties"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["proptech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-204-1', (select problem_id from problems where problem_code = 'PRP-204'), 'No Owner for the Schedule', 'Operational', 'Nobody was made responsible for the programme, so slippage is noticed only when it is obvious.', 0.76, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-204-2', (select problem_id from problems where problem_code = 'PRP-204'), 'Duties Not Written', 'Operational', 'Ordering, coordination and checking were never assigned in writing, so they overlap and leave gaps.', 0.71, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-204-3', (select problem_id from problems where problem_code = 'PRP-204'), 'Found Late, Not Predicted', 'Behavioural', 'Progress is judged by looking at the site rather than against a plan, so problems are found after they cost money.', 0.68, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
