insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('PRP-207', 'One Project at a Time, With No View Beyond It', 'Strategy & Planning', 'internal', 'The business exists to finish the current project. What kind of developer or builder it wants to be, and in which market, has never been decided, so each project is unrelated to the last.', 5, 9, '["Only the current project matters", "No stated type of work to focus on", "No written plan", "Projects unrelated to each other"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["proptech"]'::jsonb) on conflict (problem_code) do nothing;
