insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-PRP-207-3', (select problem_id from problems where problem_code = 'PRP-207'), 'No Measure of Progress', 'Knowledge', 'There is no number that says the business got stronger, only that a project finished.', 0.67, 'internal', 'Stage 0→1', '["proptech"]'::jsonb) on conflict (root_cause_code) do nothing;
